"""Build the self-contained, reviewable report from retained experiment records."""

import argparse
from collections import Counter
import html
import json
from pathlib import Path

from common import BASE, ROOT


def esc(value):
    return html.escape(str(value))


def link(path, label, line=1):
    return f'<a href="vscode://file{esc(str(Path(path).resolve()))}:{line}">{esc(label)}</a>'


def construction_review_section():
    path = BASE / "construction_review_examples.json"
    if not path.is_file():
        return ""
    records = json.loads(path.read_text())
    examples = records["examples"]
    contents = "".join(
        f'<li><a href="#review-{esc(row["id"])}">{esc(row["title"])}</a></li>'
        for row in examples
    )
    cards = []
    for number, row in enumerate(examples, 1):
        sources = "".join(link(ROOT / source["path"], source["label"], source["line"]) for source in row["sources"])
        cards.append(f'''<article class="card review-case" id="review-{esc(row['id'])}">
          <small>{esc(row['version'])}</small><h3>{number}. {esc(row['title'])}</h3>
          <p class="review-scope">{esc(row['affected'])}</p>
          <div class="review-columns"><div><h4>The mistake</h4><p>{esc(row['mistake'])}</p>
          <div class="review-example"><h4>A concrete example</h4><p>{esc(row['example'])}</p></div></div>
          <div><h4>How review caught it</h4><p>{esc(row['caught'])}</p>
          <h4>The repair</h4><p>{esc(row['repair'])}</p></div></div>
          <p class="review-lesson"><b>Why it matters.</b> {esc(row['lesson'])}</p>
          <div class="source-links">{sources}</div></article>''')
    return f'''<section id="construction-mistakes"><h2>Five earlier construction mistakes caught during review</h2>
      <p>Earlier reviews found mistakes in how the Construction Agent connected observations, packet behavior, and requirements. The examples below come from the early theory review and the v3.1 and v3.2 construction records. Each includes the original finding and a recorded repair.</p>
      <p>Three examples were caught while reviewing what the specifications meant, before their main proofs were constructed. The other two concern the snapshot importer and a MACsec processing rule. They are historical examples, separate from the 100 injected network violations and the experiment scores.</p>
      <ol class="review-index">{contents}</ol>{''.join(cards)}
      <div class="note"><p>Lean checks whether a proof establishes the statement written in Lean. Reviewing the statement and its supporting model is also essential: the statement can omit a required order, select the wrong records, or overlook relevant paths. These selected cases show how review exposed those mistakes. They do not measure the Construction Agent's overall error rate.</p></div>
      </section>'''


def path_trial_section():
    run = BASE / "runs/20261112-path-properties-01"
    summary_path = run / "supervisor-assessment.json"
    if not summary_path.exists():
        return ""
    report = json.loads(summary_path.read_text())
    runtime = json.loads((run / "detector-runtime.json").read_text())
    results = []
    for row in report["cases"]:
        results.append(f'''<tr><th scope="row">{esc(row['network'])}</th>
          <td>{esc(row['property_id'])}</td><td>{esc(row['detector_status'])}</td>
          <td>{esc(row['assessment'])}<details><summary>Reasoning and scope</summary>
          <p>{esc(row['explanation'])}</p></details></td></tr>''')
    properties = "".join(f'<li><b>{esc(row["id"])}:</b> {esc(row["description"])}</li>' for row in report["properties"])
    paragraphs = "".join(f"<p>{esc(p)}</p>" for p in report["summary"])
    methods = "".join(f'<article class="card"><h3>{esc(row["title"])}</h3><p>{esc(row["text"])}</p></article>' for row in report["methods"])
    difficulties = "".join(f"<li>{esc(p)}</li>" for p in report["difficulties"])
    limitations = "".join(f"<p>{esc(p)}</p>" for p in report["limitations"])
    sources = "".join(link(run / row["path"], row["label"], row.get("line", 1)) for row in report["sources"])
    return f'''<section id="path-trial"><h2>The additional trial asks about every possible path</h2>
      {paragraphs}<div class="stats">
      <div class="stat"><strong>{runtime['runtime_seconds']/60:.2f} min</strong><span>Total Detector runtime</span></div>
      <div class="stat"><strong>{report['established_cases']} / {report['applicable_cases']}</strong><span>Applicable questions established within the reported scope</span></div>
      <div class="stat"><strong>{esc(report['stall_label'])}</strong><span>{esc(report['stall_caption'])}</span></div></div>
      <h3>Four questions on each of the same five networks</h3><ol class="filelist">{properties}</ol>
      <p>The Detector received the original CSfC PDF, a fresh read-only gateway, and these four questions. It received no TDN proofs, previous Detector findings, injection list, reference answers, or suggested algorithm. The network configurations were left unchanged. Each question covers arbitrary finite path lengths, including alternative routes and repeated visits where relevant.</p>
      <h3>How the Detector handled the path space</h3><div class="cards">{methods}</div>
      <h3>Results and independent assessment</h3><div class="table-wrap"><table>
      <thead><tr><th>Network</th><th>Property</th><th>Detector result</th><th>Supervisor assessment</th></tr></thead>
      <tbody>{''.join(results)}</tbody></table></div>
      <h3>Runtime and difficulties</h3><p>{esc(report['runtime_explanation'])}</p><ul class="filelist">{difficulties}</ul>
      <h3>What the trial establishes</h3>{limitations}<div class="source-links">{sources}</div></section>'''


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("run_id")
    args = parser.parse_args()
    run = BASE / "runs" / args.run_id
    scores = json.loads((run / "scoring.json").read_text())
    deployments = json.loads((run / "deployments.json").read_text())
    requirements = json.loads((BASE / "legacy" / "requirements.json").read_text())
    tdn = json.loads((run / "tdn-final/results.json").read_text())
    detector = json.loads((run / "detector/findings.json").read_text())
    coverage = json.loads((run / "detector/coverage.json").read_text())["coverage"]
    profile_dir = BASE / "legacy" / "profiles"
    profiles = [json.loads(p.read_text()) for p in sorted(profile_dir.glob("net-*.json"))]
    profile_names = ["Two-site baseline", "Two networks at the same security level", "Four levels with shared Outer devices", "Four levels with redundant Outer paths", "Independent management networks"]
    file = lambda name, label: link(run / name, label)
    cards = []
    for row, name in zip(deployments, profile_names):
        role_counts = Counter(d["role"] for d in row["spec"]["devices"])
        cards.append(f'''<article class="card" id="{row['id']}"><small>{row['id']}</small><h3>{esc(name)}</h3>
          <p><strong>{len(row['spec']['devices'])} devices, {len(row['spec']['links'])} links</strong>. The original device names start with <code>{esc(row['spec']['devices'][0]['id'].split('_')[0])}_</code>.</p>
          <p>{role_counts['inner']} Inner encryptors, {role_counts['outer']} Outer encryptors, {role_counts['firewall']} Outer Firewalls, and {role_counts['gray-firewall']} Gray Firewalls.</p>
          <p class="scoreline"><span>Detector: <b>18 / 20</b></span><span>TDN: <b>12 / 20</b></span></p>
          {link(profile_dir / (row['id']+'.json'), 'Open the topology and mutations')}</article>''')
    requirement_rows = []
    for row in scores["by_requirement"]:
        req = row["requirement"]
        requirement_rows.append(f'''<tr><th scope="row"><button class="req-button" data-req="{req}">{req}</button></th>
          <td>{esc(row['description'])}<details><summary>Original requirement and assessment</summary>
          <p class="quote">{esc(requirements[req]['text'])}</p><small>PDF page {requirements[req]['page']}.</small>
          <p><b>Detector:</b> {esc(row['detector_note'])}</p><p><b>TDN:</b> {esc(row['tdn_note'])}</p></details></td>
          <td><span class="badge {'found' if row['detector'] else 'miss'}">{row['detector']} / 5</span></td>
          <td><span class="badge {'found' if row['tdn'] else 'miss'}">{row['tdn']} / 5</span></td></tr>''')
    case_rows = []
    for row in scores["cases"]:
        state = "both" if row["tdn"]["detected"] and row["detector"]["detected"] else "agent" if row["detector"]["detected"] else "neither"
        notes = "".join(f"<p><b>{name}:</b> {esc(row[key].get('reason', 'Recorded finding: '+', '.join(row[key]['findings'])))}</p>" for key, name in [("detector", "Detector"), ("tdn", "TDN")])
        case_rows.append(f'''<tr data-network="{row['network']}" data-result="{state}" data-search="{esc((row['requirement']+' '+row['device']+' '+row['description']).lower())}">
          <td>{row['network']}</td><th scope="row">{row['requirement']}</th><td><code>{esc(row['device'])}</code>
          <details><summary>Evidence and result</summary><p>{esc(row['description'])}</p>{notes}
          {file(row['validation']['source'], 'Open live ground-truth evidence')}</details></td>
          <td>{'Found' if row['detector']['detected'] else 'Withheld'}</td><td>{'Found' if row['tdn']['detected'] else 'No finding'}</td></tr>''')
    run_seconds = scores["summary"]["detector"]["runtime_seconds"]
    document = TEMPLATE.replace("{{NETWORK_CARDS}}", "".join(cards)).replace("{{REQUIREMENT_ROWS}}", "".join(requirement_rows)).replace("{{CASE_ROWS}}", "".join(case_rows))
    reviews = construction_review_section()
    if not reviews:
        document = document.replace('<a href="#construction-mistakes">Earlier construction mistakes</a>', "")
    replacements = {
        "{{RUN}}": esc(args.run_id), "{{AGENT_TIME}}": f"{run_seconds/60:.2f} minutes", "{{TDN_TIME}}": f"{tdn['runtime_seconds']:.2f} seconds",
        "{{LEAN_TIME}}": f"{tdn['lean_execution_seconds']:.2f} seconds", "{{CERT_TIME}}": f"{tdn['certificate_typecheck_seconds']:.2f} seconds",
        "{{OBSERVATIONS}}": str(len(coverage)), "{{FAILED_OBSERVATIONS}}": str(sum(r['returncode'] != 0 for r in coverage)),
        "{{SCORING}}": file("scoring.json", "All scores and case-level decisions"),
        "{{AGENT_RESULTS}}": file("detector/findings.json", "Original Detector response"),
        "{{AGENT_PROMPT}}": file("detector-prompt.txt", "Exact Detector instructions"),
        "{{ACCESS_AUDIT}}": file("detector-access-audit.json", "Access audit and verified model settings"),
        "{{TOOL_CALLS}}": file("detector-tool-calls.json", "All 19 recorded tool invocations"),
        "{{TDN_RESULTS}}": file("tdn-final/results.json", "TDN results and source observations"),
        "{{TDN_SOURCE}}": link(BASE / "tdn_evaluate.py", "Read the experiment adapter"),
        "{{PACKET_SOURCE}}": link(BASE / "PacketChecks.lean", "Read the Lean executable driver"),
        "{{CERT_SOURCE}}": link(BASE / "CertificateChecks.lean", "Read the checked certificate theorem"),
        "{{MODEL_SOURCE}}": link(ROOT / "TDN/Models/IpsecAndAclRuleModel.lean", "TDN packet and policy definitions", 159),
        "{{ORDER_SOURCE}}": link(ROOT / "TDN/Models/OrderedAclFilter.lean", "TDN first-match filter evaluation", 14),
        "{{SPD_SOURCE}}": link(ROOT / "TDN/Models/DataPlaneForwarding.lean", "TDN IPsec selector matching", 78),
        "{{CONFIG_SOURCE}}": link(ROOT / "scripts/construction/check_configuration_records.py", "Existing configuration audits", 150),
        "{{LIFETIME_SOURCE}}": link(ROOT / "TDN/Requirements/CsfcRoleObligationRecords.lean", "Formalized IKE and ESP configuration clauses", 484),
        "{{PARSER_SOURCE}}": link(ROOT / "scripts/construction/loaded_policy.py", "Strict public-configuration parser", 7),
        "{{INITIAL_REPLAY}}": file("tdn-live-replay.json", "Initial live replay: 20 of 30 packets observed"),
        "{{FIXED_REPLAY}}": file("tdn-live-compatible-replay.json", "Revised live replay: 30 of 30 packets observed"),
        "{{REPAIR}}": file("tdn-witness-source-adjustments.json", "The ten source-address adjustments"),
        "{{FREEZE}}": file("tdn-freeze.json", "Frozen TDN inputs and results"),
        "{{INJECTIONS}}": file("injection-freeze.json", "Predeclared requirements and mutation hashes"),
        "{{MAINTENANCE}}": file("raw/baseline-maintenance.json", "Baseline backups and CRL renewal"),
        "{{README}}": link(BASE / "README.md", "Run, inspect, replay, and restore instructions"),
        "{{PROFILES}}": link(profile_dir / "net-01.json", "Start with the first noncompliant profile"),
        "{{ROLLBACK}}": link(BASE / "rollback.py", "Restore the saved clean configurations"),
        "{{PDF}}": link(ROOT / "docs/CSfC_documentation_v1.3.0.pdf", "Original CSfC CP 1.3.0"),
        "{{REPORT_GENERATOR}}": link(BASE / "build_report.py", "Report generator"),
        "{{CONSTRUCTION_REVIEWS}}": reviews,
        "{{PATH_TRIAL}}": path_trial_section(),
    }
    for key, value in replacements.items():
        document = document.replace(key, value)
    document = document.replace('<svg class="diagram"', '<div class="figure-wrap"><svg class="diagram"').replace("</svg>", "</svg></div>")
    assert "{{" not in document
    target = ROOT / ".lavish/agent-baseline.html"
    target.write_text(document)
    print(target)


